<?php

namespace Askancy\LaravelSmartThumbnails\Tests\Unit;

use Askancy\LaravelSmartThumbnails\Support\PixelBudget;
use Askancy\LaravelSmartThumbnails\Tests\TestCase;

/**
 * A thumbnail is generated by decoding the source image first, and the decoder
 * allocates width x height x 4 bytes no matter how small the compressed file
 * is. A 139 megapixel PNG is a few MB on disk and needs ~530 MB of RAM: the
 * process dies with "Allowed memory size exhausted" and takes the whole
 * request (or the queue worker) with it.
 *
 * The file size tells you nothing about the pixel count — that is what makes a
 * decompression bomb work. getimagesize() reads only the header, so the real
 * size is known before anything is allocated.
 */
class PixelBudgetTest extends TestCase
{
    public function test_it_reports_the_megapixels_of_an_image(): void
    {
        $this->assertSame(0.5, PixelBudget::megapixels($this->pngBinary(1000, 500)));
    }

    public function test_an_image_over_the_budget_is_rejected(): void
    {
        $this->assertTrue(PixelBudget::exceeds($this->pngBinary(1000, 500), 0.4));
    }

    public function test_an_image_within_the_budget_is_allowed(): void
    {
        $this->assertFalse(PixelBudget::exceeds($this->pngBinary(1000, 500), 0.6));
    }

    /**
     * The guard covers one failure mode and must not become a second one: what
     * it cannot measure goes through, and the decoder fails on its own with
     * its own error.
     */
    public function test_what_cannot_be_measured_is_not_blocked(): void
    {
        $this->assertNull(PixelBudget::megapixels('this is not an image'));
        $this->assertFalse(PixelBudget::exceeds('this is not an image', 0.1));
    }

    public function test_zero_or_negative_budget_disables_the_guard(): void
    {
        $binary = $this->pngBinary(1000, 500);

        $this->assertFalse(PixelBudget::exceeds($binary, 0));
        $this->assertFalse(PixelBudget::exceeds($binary, -1));
    }

    public function test_the_budget_comes_from_config_with_a_sane_default(): void
    {
        config(['thumbnails.max_megapixels' => 12.5]);
        $this->assertSame(12.5, PixelBudget::configuredBudget());

        config(['thumbnails.max_megapixels' => null]);
        $this->assertSame(60.0, PixelBudget::configuredBudget());
    }

    private function pngBinary(int $width, int $height): string
    {
        $gd = imagecreatetruecolor($width, $height);

        ob_start();
        imagepng($gd);
        $binary = (string) ob_get_clean();

        imagedestroy($gd);

        return $binary;
    }
}
